//! Language-neutral value descriptor. Complete artifact/provider operations
//! remain distinct from this HTML fragment structural request.
mod descriptor;
pub use descriptor::descriptor;
use nepl3_core::schema::*;

//! XML 1.0 character admission and canonical text/attribute escaping.
//! No input character is silently replaced or removed.
use alloc::string::String;
use nepl3_core::budget::{Budget, Resource, StopReason};

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum TextContext {
    Content,
    /// A double-quoted attribute in a fixed element/attribute name.
    Attribute,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum TextError {
    InvalidCharacter { byte: u64, scalar: u64 },
    Stopped(StopReason),
}
impl From<StopReason> for TextError {
    fn from(reason: StopReason) -> Self {
        Self::Stopped(reason)
    }
}

/// XML 1.0 Fifth Edition Char, evaluated on an already valid Rust scalar.
pub fn is_xml_character(c: char) -> bool {
    matches!(c, '\u{9}' | '\u{a}' | '\u{d}' | '\u{20}'..='\u{d7ff}' | '\u{e000}'..='\u{fffd}' | '\u{10000}'..='\u{10ffff}')
}

fn replacement(c: char, context: TextContext) -> Option<&'static str> {
    match (c, context) {
        ('&', _) => Some("&amp;"),
        ('<', _) => Some("&lt;"),
        ('>', _) => Some("&gt;"),
        // A literal CR is normalized by XML/HTML parsing even in text content.
        ('\r', _) => Some("&#xD;"),
        ('"', TextContext::Attribute) => Some("&quot;"),
        ('\n', TextContext::Attribute) => Some("&#xA;"),
        ('\t', TextContext::Attribute) => Some("&#x9;"),
        _ => None,
    }
}

/// Return the complete escaped text, or a typed error without a partial string.
/// Charges validation work and exact output bytes before allocating the result.
/// Input is a semantic value: source admission is its caller's separate duty.
pub fn escape(text: &str, context: TextContext, budget: &mut Budget) -> Result<String, TextError> {
    budget.charge(Resource::Work, text.len() as u64)?;
    let mut length = 0_u64;
    for (byte, c) in text.char_indices() {
        if !is_xml_character(c) {
            return Err(TextError::InvalidCharacter {
                byte: byte as u64,
                scalar: u64::from(c),
            });
        }
        let size = replacement(c, context).map_or(c.len_utf8(), str::len) as u64;
        length = length
            .checked_add(size)
            .ok_or_else(|| budget.stop(StopReason::OutputLimit))?;
    }
    budget.charge(Resource::Work, length)?;
    // This stage produces bytes rather than a markup node. Nodes and logical
    // tree depth are accounted for by the tree serializer that calls it.
    budget.charge(Resource::OutputBytes, length)?;
    budget.charge(Resource::AllocationUnits, length)?;
    let capacity = usize::try_from(length).map_err(|_| budget.stop(StopReason::AllocationLimit))?;
    if capacity > isize::MAX as usize {
        return Err(budget.stop(StopReason::AllocationLimit).into());
    }
    let mut output = String::with_capacity(capacity);
    for c in text.chars() {
        if let Some(escaped) = replacement(c, context) {
            output.push_str(escaped);
        } else {
            output.push(c);
        }
    }
    Ok(output)
}

use nepl3_core::budget::{Budget, Limits, StopReason};
use nepl3_markup::html::*;
fn budget() -> Budget {
    Budget::new(Limits {
        work: 100_000_000,
        allocation_units: 100_000_000,
        output_bytes: 10_000_000,
        nodes: 2_000_000,
        depth: 200_000,
        ..Limits::default()
    })
}
fn policy() -> HtmlPolicy {
    HtmlPolicy {
        classes: vec!["doc-paragraph".into()],
    }
}
fn element(tag: HtmlTag, children: &[u64]) -> HtmlNode {
    HtmlNode::Element {
        tag,
        children: children.into(),
        attributes: vec![],
    }
}
fn txt(text: &str) -> HtmlNode {
    HtmlNode::Text { text: text.into() }
}
fn attr(node: &mut HtmlNode, a: HtmlAttribute) {
    if let HtmlNode::Element { attributes, .. } = node {
        attributes.push(a);
    }
}
fn render(f: &HtmlFragment) -> Result<String, HtmlError> {
    let mut b = budget();
    serialize(&validate(f, HtmlSlot::Block, &policy(), &mut b)?, &mut b)
}

#[test]
fn nested_paragraph_wrapper_links_lists_and_code_preserve_bytes() -> Result<(), HtmlError> {
    use HtmlTag::*;
    let mut f = HtmlFragment {
        root: 0,
        nodes: vec![
            element(Article, &[1, 3, 6]),
            element(H1, &[2]),
            txt("日本語🙂"),
            element(Div, &[4, 8]),
            element(P, &[5]),
            txt("<&\r\n"),
            element(Pre, &[7]),
            txt("\nlet x = \"<&\";\r\n"),
            element(Ul, &[9]),
            element(Li, &[10]),
            element(A, &[11]),
            txt("先頭へ"),
        ],
    };
    attr(
        &mut f.nodes[1],
        HtmlAttribute::Id {
            value: "title".into(),
        },
    );
    attr(&mut f.nodes[1], HtmlAttribute::Lang { value: "ja".into() });
    attr(
        &mut f.nodes[3],
        HtmlAttribute::Class {
            values: vec!["doc-paragraph".into()],
        },
    );
    attr(
        &mut f.nodes[10],
        HtmlAttribute::Href {
            value: HtmlHref::Fragment { id: "title".into() },
        },
    );
    let expected = "<article><h1 id=\"title\" lang=\"ja\">日本語🙂</h1><div class=\"doc-paragraph\"><p>&lt;&amp;&#xD;\n</p><ul><li><a href=\"#title\">先頭へ</a></li></ul></div><pre>\n\nlet x = \"&lt;&amp;\";&#xD;\n</pre></article>";
    assert_eq!(render(&f)?, expected);
    if let HtmlNode::Element { attributes, .. } = &mut f.nodes[1] {
        attributes.reverse();
    }
    assert_eq!(render(&f)?, expected);
    Ok(())
}

