#[test]
fn malformed_structure_and_attribute_values_never_become_partial_html() {
    use HtmlTag::*;
    for (inside, descendant) in [(Caption, Table), (Th, H1), (Th, Section)] {
        let nodes = if inside == Caption {
            vec![
                element(Table, &[1]),
                element(Caption, &[2]),
                element(Div, &[3]),
                element(descendant, &[]),
            ]
        } else {
            vec![
                element(Table, &[1]),
                element(Tbody, &[2]),
                element(Tr, &[3]),
                element(Th, &[4]),
                element(Div, &[5]),
                element(descendant, &[]),
            ]
        };
        assert!(render(&HtmlFragment { root: 0, nodes }).is_err());
    }
    let ragged = HtmlFragment {
        root: 0,
        nodes: vec![
            element(Table, &[1]),
            element(Tbody, &[2, 3]),
            element(Tr, &[4]),
            element(Tr, &[5, 6]),
            element(Td, &[]),
            element(Td, &[]),
            element(Td, &[]),
        ],
    };
    assert!(render(&ragged).is_err());
    for (parent, child) in [
        (P, Div),
        (Span, Table),
        (Table, Tr),
        (Ul, Div),
        (Tr, Div),
        (Img, Span),
        (Br, Span),
        (A, A),
    ] {
        let f = HtmlFragment {
            root: 0,
            nodes: vec![element(parent, &[1]), element(child, &[])],
        };
        assert!(render(&f).is_err(), "{parent:?}/{child:?}");
    }
    for uri in [
        "javascript:alert(1)",
        "data:text/html,test",
        "HTTPS://example.org",
        "https://user@example.org/",
        "https://example.org/\\x",
        "https://example.org/\tx",
        "https://example.org/%xx",
        "//example.org",
    ] {
        let mut a = element(A, &[]);
        attr(
            &mut a,
            HtmlAttribute::Href {
                value: HtmlHref::External { uri: uri.into() },
            },
        );
        assert!(
            matches!(
                render(&HtmlFragment {
                    root: 0,
                    nodes: vec![a]
                }),
                Err(HtmlError::Attribute { .. })
            ),
            "{uri}"
        );
    }
    for path in [
        "/root.png",
        "../secret.png",
        "a/../secret.png",
        "//host/x",
        "a%2fb.png",
        "a\\b.png",
    ] {
        let mut n = element(Img, &[]);
        attr(&mut n, HtmlAttribute::Src { path: path.into() });
        attr(&mut n, HtmlAttribute::Alt { value: "".into() });
        assert!(
            matches!(
                render(&HtmlFragment {
                    root: 0,
                    nodes: vec![n]
                }),
                Err(HtmlError::Attribute { .. })
            ),
            "{path}"
        );
    }
    let mut n = element(Div, &[]);
    attr(
        &mut n,
        HtmlAttribute::Class {
            values: vec!["unregistered".into()],
        },
    );
    assert!(
        render(&HtmlFragment {
            root: 0,
            nodes: vec![n]
        })
        .is_err()
    );
    let mut n = element(Div, &[]);
    attr(&mut n, HtmlAttribute::Id { value: "a".into() });
    attr(&mut n, HtmlAttribute::Id { value: "b".into() });
    assert!(
        render(&HtmlFragment {
            root: 0,
            nodes: vec![n]
        })
        .is_err()
    );
}

#[test]
fn dag_appearance_identity_cycles_unreachable_and_deep_drop() -> Result<(), HtmlError> {
    let mut f = HtmlFragment {
        root: 0,
        nodes: vec![
            element(HtmlTag::Div, &[1, 1]),
            element(HtmlTag::Span, &[2]),
            txt("x"),
        ],
    };
    assert_eq!(render(&f)?, "<div><span>x</span><span>x</span></div>");
    attr(
        &mut f.nodes[1],
        HtmlAttribute::Id {
            value: "shared".into(),
        },
    );
    assert_eq!(render(&f), Err(HtmlError::DuplicateId(1)));
    assert!(matches!(
        render(&HtmlFragment {
            root: 0,
            nodes: vec![element(HtmlTag::Div, &[0])]
        }),
        Err(HtmlError::Cycle(0))
    ));
    assert!(matches!(
        render(&HtmlFragment {
            root: 0,
            nodes: vec![txt("x"), txt("y")]
        }),
        Err(HtmlError::Unreachable(1))
    ));
    assert!(matches!(
        render(&HtmlFragment {
            root: u64::MAX,
            nodes: vec![]
        }),
        Err(HtmlError::Reference(u64::MAX))
    ));
    let mut nodes = Vec::new();
    for i in 0..100_000 {
        nodes.push(element(HtmlTag::Div, &[i + 1]));
    }
    nodes.push(txt("終"));
    let deep = HtmlFragment { root: 0, nodes };
    assert!(validate(&deep, HtmlSlot::Block, &policy(), &mut budget()).is_ok());
    drop(deep);
    Ok(())
}

#[test]
fn sticky_stops_apply_to_validation_and_serialization_with_caller_depth() -> Result<(), HtmlError> {
    let f = HtmlFragment {
        root: 0,
        nodes: vec![element(HtmlTag::Span, &[1]), txt("<&🙂")],
    };
    let proof = validate(&f, HtmlSlot::Phrasing, &policy(), &mut budget())?;
    let output = serialize(&proof, &mut budget())?;
    for reason in [
        StopReason::WorkLimit,
        StopReason::DepthLimit,
        StopReason::NodeLimit,
        StopReason::AllocationLimit,
        StopReason::OutputLimit,
        StopReason::Cancelled,
    ] {
        let mut limits = budget().limits();
        match reason {
            StopReason::WorkLimit => limits.work = 0,
            StopReason::DepthLimit => limits.depth = 1,
            StopReason::NodeLimit => limits.nodes = 0,
            StopReason::AllocationLimit => limits.allocation_units = 0,
            StopReason::OutputLimit => limits.output_bytes = output.len() as u64 - 1,
            _ => {}
        }
        let mut b = Budget::new(limits);
        if reason == StopReason::Cancelled {
            b.cancel();
        }
        assert_eq!(serialize(&proof, &mut b), Err(HtmlError::Stopped(reason)));
        assert_eq!(serialize(&proof, &mut b), Err(HtmlError::Stopped(reason)));
    }
    let mut b = Budget::new(Limits {
        depth: 8,
        ..budget().limits()
    });
    let result = b.with_depth_at_least(7, |b| serialize(&proof, b));
    assert_eq!(result, Err(HtmlError::Stopped(StopReason::DepthLimit)));
    let mut exact = Budget::new(Limits {
        output_bytes: output.len() as u64,
        ..budget().limits()
    });
    assert_eq!(serialize(&proof, &mut exact)?, output);
    assert_eq!(exact.usage().output_bytes, output.len() as u64);
    Ok(())
}

use nepl3_core::{
    budget::{Budget, Limits, StopReason},
    schema::SchemaRegistry,
    source::{SourceAdmission, SourceStore},
    value::NdfValue,
};
use nepl3_markup::{
    html::*,
    portable::{self, PortableError},
};
use nepl3_wire::foundation::FoundationCodec;
fn b() -> Budget {
    Budget::new(Limits {
        work: 100_000_000,
        allocation_units: 100_000_000,
        nodes: 1_000_000,
        depth: 1000,
        output_bytes: 10_000_000,
        ..Limits::default()
    })
}
fn err(e: impl core::fmt::Debug) -> String {
    format!("{e:?}")
}
fn registry() -> Result<SchemaRegistry, String> {
    let mut r = SchemaRegistry::default();
    for d in [
        nepl3_core::schema::foundation::descriptor(&mut b()),
        nepl3_markup::schema::descriptor(&mut b()),
    ] {
        let d = d.map_err(err)?;
        r.register(d.reference(&mut b()).map_err(err)?, d, &mut b())
            .map_err(err)?;
    }
    r.finalize(&mut b()).map_err(err)?;
    Ok(r)
}
fn request() -> HtmlRequest {
    HtmlRequest {
        slot: HtmlSlot::Phrasing,
        policy: HtmlPolicy { classes: vec![] },
        fragment: HtmlFragment {
            root: 0,
            nodes: vec![
                HtmlNode::Element {
                    tag: HtmlTag::Span,
                    attributes: vec![
                        HtmlAttribute::Lang { value: "ja".into() },
                        HtmlAttribute::Id {
                            value: "n-a".into(),
                        },
                    ],
                    children: vec![1],
                },
                HtmlNode::Text {
                    text: "あ🙂<&\r\n".into(),
                },
            ],
        },
    }
}

#[test]
fn first_cbor_receiver_revalidates_owned_markup_and_matches_native_output() -> Result<(), String> {
    let r = registry()?;
    let original = request();
    let bytes = {
        let store = SourceStore::default();
        let mut a = SourceAdmission::default();
        let mut c = FoundationCodec::new(&r, &store, &mut a).map_err(err)?;
        let value = portable::to_value(&original, &r, &mut c, &mut b()).map_err(err)?;
        nepl3_wire::encode(&value, &mut b()).map_err(err)?
    };
    let store = SourceStore::default();
    let mut a = SourceAdmission::default();
    let mut c = FoundationCodec::new(&r, &store, &mut a).map_err(err)?;
    let received = nepl3_wire::decode(&bytes, &mut b()).map_err(err)?;
    let actual = portable::from_value(&received, &r, &mut c, &mut b()).map_err(err)?;
    assert_eq!(actual, original);
    let proof = validate(&actual.fragment, actual.slot, &actual.policy, &mut b()).map_err(err)?;
    assert_eq!(
        serialize(&proof, &mut b()).map_err(err)?,
        "<span id=\"n-a\" lang=\"ja\">あ🙂&lt;&amp;&#xD;\n</span>"
    );
    assert_eq!(
        nepl3_wire::encode(
            &portable::to_value(&actual, &r, &mut c, &mut b()).map_err(err)?,
            &mut b()
        )
        .map_err(err)?,
        bytes
    );
    Ok(())
}

#[test]
fn schema_valid_invalid_markup_and_unknown_tags_are_rejected_after_cbor() -> Result<(), String> {
    let r = registry()?;
    let store = SourceStore::default();
    let mut a = SourceAdmission::default();
    let mut c = FoundationCodec::new(&r, &store, &mut a).map_err(err)?;
    let value = portable::to_value(&request(), &r, &mut c, &mut b()).map_err(err)?;
    for bad in 0..4 {
        let mut v = value.clone();
        let NdfValue::Record(req) = &mut v else {
            return Err("request".into());
        };
        let NdfValue::Record(fragment) = &mut req.fields[0] else {
            return Err("fragment".into());
        };
        let NdfValue::List(nodes) = &mut fragment.fields[1] else {
            return Err("nodes".into());
        };
        if bad == 0 {
            fragment.fields[0] = NdfValue::U64(u64::MAX);
        } else if bad == 1 {
            let NdfValue::Variant(text) = &mut nodes[1] else {
                return Err("text".into());
            };
            text.fields[0] = NdfValue::Text("あ\0".into());
        } else {
            let NdfValue::Variant(element) = &mut nodes[0] else {
                return Err("element".into());
            };
            if bad == 2 {
                let NdfValue::Variant(tag) = &mut element.fields[0] else {
                    return Err("tag".into());
                };
                tag.variant = "Script".into();
            } else {
                element.fields[2] = NdfValue::List(vec![NdfValue::U64(0)]);
            }
        }
        let bytes = nepl3_wire::encode(&v, &mut b()).map_err(err)?;
        let decoded = nepl3_wire::decode(&bytes, &mut b()).map_err(err)?;
        assert!(
            portable::from_value(&decoded, &r, &mut c, &mut b()).is_err(),
            "mutation {bad}"
        );
    }
    for reason in [
        StopReason::WorkLimit,
        StopReason::AllocationLimit,
        StopReason::DepthLimit,
        StopReason::Cancelled,
    ] {
        let mut limits = b().limits();
        match reason {
            StopReason::WorkLimit => limits.work = 0,
            StopReason::AllocationLimit => limits.allocation_units = 0,
            StopReason::DepthLimit => limits.depth = 0,
            _ => {}
        }
        let mut budget = Budget::new(limits);
        if reason == StopReason::Cancelled {
            budget.cancel();
        }
        assert_eq!(
            portable::from_value(&value, &r, &mut c, &mut budget),
            Err(PortableError::Stopped(reason))
        );
        assert_eq!(
            portable::from_value(&value, &r, &mut c, &mut budget),
            Err(PortableError::Stopped(reason))
        );
    }
    Ok(())
}

