use nepl3_core::budget::{Budget,Limits};
use nepl3_markup::html::*;
#[test]
fn constrained_port_lexical_boundaries(){
 for uri in ["https://example.org:80/","https://example.org:65535/","https://example.org:65536/","https://example.org:+80/","https://example.org:+0/","https://example.org:-0/","https://example.org:/","https://example.org:80x/","https://example.org/a%0a","https://example.org/%","https://example.org/%2"] {
  let f=HtmlFragment{root:0,nodes:vec![HtmlNode::Element{tag:HtmlTag::A,attributes:vec![HtmlAttribute::Href{value:HtmlHref::External{uri:uri.into()}}],children:vec![]}]};
  let p=HtmlPolicy{classes:vec![]};let mut b=Budget::new(Limits{work:100000,allocation_units:100000,nodes:1000,depth:100,output_bytes:10000,..Limits::default()});
  let result=validate(&f,HtmlSlot::Phrasing,&p,&mut b);println!("URI {uri} accepted={}",result.is_ok());
 }
}

use nepl3_core::{budget::{Budget,Limits},schema::SchemaRegistry,source::{SourceAdmission,SourceStore},value::NdfValue};
use nepl3_markup::{html::*,portable};
use nepl3_wire::foundation::FoundationCodec;
fn b()->Budget {Budget::new(Limits{work:100_000_000,allocation_units:100_000_000,nodes:2_000_000,depth:200_000,output_bytes:10_000_000,..Limits::default()})}
fn e(tag:HtmlTag,children:Vec<u64>,attributes:Vec<HtmlAttribute>)->HtmlNode {HtmlNode::Element{tag,children,attributes}}
fn t(s:&str)->HtmlNode {HtmlNode::Text{text:s.into()}}
fn registry()->SchemaRegistry {let mut r=SchemaRegistry::default();for d in [nepl3_core::schema::foundation::descriptor(&mut b()).unwrap(),nepl3_markup::schema::descriptor(&mut b()).unwrap()]{r.register(d.reference(&mut b()).unwrap(),d,&mut b()).unwrap();}r.finalize(&mut b()).unwrap();r}
fn req(nodes:Vec<HtmlNode>)->HtmlRequest {HtmlRequest{fragment:HtmlFragment{root:0,nodes},slot:HtmlSlot::Block,policy:HtmlPolicy{classes:vec!["known".into()]}}}
fn transfer(value:&NdfValue,r:&SchemaRegistry)->Result<HtmlRequest,String> {let bytes=nepl3_wire::encode(value,&mut b()).unwrap();let decoded=nepl3_wire::decode(&bytes,&mut b()).unwrap();let store=SourceStore::default();let mut admission=SourceAdmission::default();let mut c=FoundationCodec::new(r,&store,&mut admission).unwrap();portable::from_value(&decoded,r,&mut c,&mut b()).map_err(|e|format!("{e:?}"))}
fn encode(q:&HtmlRequest,r:&SchemaRegistry)->NdfValue {let store=SourceStore::default();let mut admission=SourceAdmission::default();let mut c=FoundationCodec::new(r,&store,&mut admission).unwrap();portable::to_value(q,r,&mut c,&mut b()).unwrap()}
#[test]
fn signed_port_first_receiver(){
 let r=registry();let q=req(vec![e(HtmlTag::A,vec![],vec![HtmlAttribute::Href{value:HtmlHref::External{uri:"https://example.org:80/".into()}}])]);
 let good=encode(&q,&r);assert!(transfer(&good,&r).is_ok());
 for uri in ["https://example.org:+80/","https://example.org:+0/"] {
  let mut raw=good.clone();let NdfValue::Record(request)=&mut raw else {panic!()};let NdfValue::Record(fragment)=&mut request.fields[0] else {panic!()};let NdfValue::List(nodes)=&mut fragment.fields[1] else {panic!()};let NdfValue::Variant(element)=&mut nodes[0] else {panic!()};let NdfValue::List(attrs)=&mut element.fields[1] else {panic!()};let NdfValue::Variant(href)=&mut attrs[0] else {panic!()};let NdfValue::Variant(external)=&mut href.fields[0] else {panic!()};external.fields[0]=NdfValue::Text(uri.into());
  let got=transfer(&raw,&r);println!("URI_CBOR {uri} accepted={}",got.is_ok());
  if let Ok(got)=got {println!("URI_HTML {}",serialize(&validate(&got.fragment,got.slot,&got.policy,&mut b()).unwrap(),&mut b()).unwrap());}
 }
}

